68	func (s *Server) getCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
69		c, ok := s.store.Customer(p.OrgID, r.PathValue("id"))
70		if !ok {
71			writeError(w, http.StatusNotFound, "not_found", "no such customer")
72			return
73		}
74		writeJSON(w, http.StatusOK, c)
75	}
