77	func (s *Server) updateCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
78		var in struct {
79			Name                 *string            `json:"name"`
80			Email                *string            `json:"email"`
81			DefaultPaymentMethod *string            `json:"default_payment_method"`
82			Metadata             *map[string]string `json:"metadata"`
83		}
84		if !decode(w, r, &in) {
85			return
86		}
87		c, err := s.store.UpdateCustomer(p.OrgID, r.PathValue("id"), func(c *store.Customer) error {
88			if in.Name != nil {
89				c.Name = *in.Name
90			}
91			if in.Email != nil {
92				c.Email = *in.Email
93			}
94			if in.DefaultPaymentMethod != nil {
95				c.DefaultPaymentMethod = *in.DefaultPaymentMethod
96			}
97			if in.Metadata != nil {
98				c.Metadata = *in.Metadata
99			}
100			return nil
101		})
102		if err != nil {
103			s.storeError(w, err)
104			return
105		}
106		s.publish(r.Context(), p.OrgID, "customer.updated", c)
107		writeJSON(w, http.StatusOK, c)
108	}
