110	func (s *Server) deleteCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
111		id := r.PathValue("id")
112		if err := s.store.DeleteCustomer(p.OrgID, id); err != nil {
113			s.storeError(w, err)
114			return
115		}
116		s.publish(r.Context(), p.OrgID, "customer.deleted", map[string]string{"id": id})
117		w.WriteHeader(http.StatusNoContent)
118	}
