1	package api
2	
3	import (
4		"encoding/base64"
5		"encoding/json"
6		"errors"
7		"io"
8		"net/http"
9		"strconv"
10		"time"
11	
12		"example.com/tally/internal/store"
13	)
14	
15	func writeJSON(w http.ResponseWriter, status int, v any) {
16		w.Header().Set("Content-Type", "application/json")
17		w.WriteHeader(status)
18		_ = json.NewEncoder(w).Encode(v)
19	}
20	
21	// writeError answers {"error": code, "message": message}.
22	func writeError(w http.ResponseWriter, status int, code, message string) {
23		writeJSON(w, status, map[string]string{"error": code, "message": message})
24	}
25	
26	// decode reads a JSON body (at most 1 MiB) into v, or answers 400 and returns false.
27	func decode(w http.ResponseWriter, r *http.Request, v any) bool {
28		dec := json.NewDecoder(io.LimitReader(r.Body, 1<<20))
29		if err := dec.Decode(v); err != nil {
30			writeError(w, http.StatusBadRequest, "invalid_json", "the body is not valid JSON: "+err.Error())
31			return false
32		}
33		return true
34	}
35	
36	// storeError answers for an error from the store or a service.
37	func (s *Server) storeError(w http.ResponseWriter, err error) {
38		switch {
39		case errors.Is(err, store.ErrNotFound):
40			writeError(w, http.StatusNotFound, "not_found", "no such object")
41		case errors.Is(err, store.ErrEmailTaken):
42			writeError(w, http.StatusConflict, "email_taken", err.Error())
43		case errors.Is(err, store.ErrAlreadyMember):
44			writeError(w, http.StatusConflict, "already_member", err.Error())
45		case errors.Is(err, store.ErrConflict):
46			writeError(w, http.StatusConflict, "conflict", err.Error())
47		case errors.Is(err, store.ErrCustomerOrgMismatch):
48			writeError(w, http.StatusUnprocessableEntity, "customer_org_mismatch", err.Error())
49		case errors.Is(err, store.ErrInvalid):
50			writeError(w, http.StatusUnprocessableEntity, "invalid", err.Error())
51		default:
52			s.log.Error("request failed", "err", err)
53			writeError(w, http.StatusInternalServerError, "internal", "something went wrong")
54		}
