97		if err := f(&c); err != nil {
98			return Customer{}, err
99		}
100		c.ID, c.OrgID, c.CreatedAt = old.ID, old.OrgID, old.CreatedAt
101		c.Name, c.Email = strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
