140	// ImportError says why the customer at Index in the import cannot be created: one of "missing_name", "invalid_email",
141	// "invalid_payment_method", "email_taken" or "duplicate_email".
142	type ImportError struct {
143		Index int
144		Code  string
145	}
146	
147	// ImportCustomers creates the customers in order, all or none. Each one is checked as CreateCustomer and UpdateCustomer
148	// check it, and its email must not belong to one of the organization's customers or to one before it, ignoring case.
149	// When any is refused, nothing is created and the refusals come back in order, with the first problem each has. With
150	// dryRun, the customers are only checked.
151	func (s *Store) ImportCustomers(orgID string, in []CustomerImport, now time.Time, dryRun bool) ([]Customer, []ImportError, error) {
152		s.mu.Lock()
153		defer s.mu.Unlock()
154		if _, ok := s.orgs[orgID]; !ok {
155			return nil, nil, ErrNotFound
156		}
157		existing := map[string]bool{}
158		for _, c := range s.customers {
159			if c.OrgID == orgID {
160				existing[normEmail(c.Email)] = true
161			}
162		}
163		earlier := map[string]bool{}
164		var refused []ImportError
165		for i, c := range in {
166			name, email := strings.TrimSpace(c.Name), strings.TrimSpace(c.Email)
167			key := normEmail(email)
168			code := ""
169			switch {
170			case name == "":
171				code = "missing_name"
172			case !validEmail(email):
173				code = "invalid_email"
174			case c.DefaultPaymentMethod != "" && !strings.HasPrefix(c.DefaultPaymentMethod, "pm_"):
175				code = "invalid_payment_method"
176			case existing[key]:
177				code = "email_taken"
178			case earlier[key]:
179				code = "duplicate_email"
180			}
181			if code != "" {
182				refused = append(refused, ImportError{Index: i, Code: code})
183			}
184			earlier[key] = true
185		}
186		if len(refused) > 0 || dryRun {
187			return nil, refused, nil
188		}
189		out := make([]Customer, 0, len(in))
190		for _, c := range in {
191			k := Customer{ID: s.newID("cus"), OrgID: orgID, Name: strings.TrimSpace(c.Name), Email: strings.TrimSpace(c.Email),
192				DefaultPaymentMethod: c.DefaultPaymentMethod, CreatedAt: now.UTC()}
193			if len(c.Metadata) > 0 {
194				k.Metadata = maps.Clone(c.Metadata)
195			}
196			s.customers[k.ID] = k
197			s.customersByEmail[normEmail(k.Email)] = k.ID
198			out = append(out, copyCustomer(k))
199		}
200		return out, nil, nil
201	}
202	
203	func copyCustomer(c Customer) Customer {
204		if c.Metadata != nil {
205			m := make(map[string]string, len(c.Metadata))
206			for k, v := range c.Metadata {
207				m[k] = v
208			}
209			c.Metadata = m
210		}
211		return c
212	}
213	
214	func sortCustomers(cs []Customer) {
215		sort.Slice(cs, func(i, j int) bool {
216			if !cs[i].CreatedAt.Equal(cs[j].CreatedAt) {
217				return cs[i].CreatedAt.Before(cs[j].CreatedAt)
218			}
219			return cs[i].ID < cs[j].ID
220		})
221	}
