44		var in struct {
45			Name                 string            `json:"name"`
46			Email                string            `json:"email"`
47			DefaultPaymentMethod string            `json:"default_payment_method"`
48			Metadata             map[string]string `json:"metadata"`
49		}
50		if !decode(w, r, &in) {
51			return
52		}
53		c, err := s.store.CreateCustomer(p.OrgID, in.Name, in.Email, s.clock.Now())
54		if err != nil {
55			s.storeError(w, err)
56			return
57		}
58		if in.DefaultPaymentMethod != "" || len(in.Metadata) > 0 {
59			c, err = s.store.UpdateCustomer(p.OrgID, c.ID, func(c *store.Customer) error {
60				c.DefaultPaymentMethod, c.Metadata = in.DefaultPaymentMethod, in.Metadata
61				return nil
62			})
63			if err != nil {
64				_ = s.store.DeleteCustomer(p.OrgID, c.ID)
65				s.storeError(w, err)
66				return
67			}
68		}
69		s.publish(r.Context(), p.OrgID, "customer.created", c)
70		writeJSON(w, http.StatusCreated, c)
71	}
