73	func (s *Server) getCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
74		c, ok := s.store.Customer(p.OrgID, r.PathValue("id"))
75		if !ok {
76			writeError(w, http.StatusNotFound, "not_found", "no such customer")
77			return
78		}
79		writeJSON(w, http.StatusOK, c)
80	}
