82	func (s *Server) updateCustomer(w http.ResponseWriter, r *http.Request, p auth.Principal) {
83		var in struct {
84			Name                 *string            `json:"name"`
85			Email                *string            `json:"email"`
86			DefaultPaymentMethod *string            `json:"default_payment_method"`
87			Metadata             *map[string]string `json:"metadata"`
88		}
89		if !decode(w, r, &in) {
90			return
91		}
92		c, err := s.store.UpdateCustomer(p.OrgID, r.PathValue("id"), func(c *store.Customer) error {
93			if in.Name != nil {
94				c.Name = *in.Name
95			}
96			if in.Email != nil {
97				c.Email = *in.Email
98			}
99			if in.DefaultPaymentMethod != nil {
100				c.DefaultPaymentMethod = *in.DefaultPaymentMethod
101			}
102			if in.Metadata != nil {
103				c.Metadata = *in.Metadata
104			}
105			return nil
106		})
107		if err != nil {
108			s.storeError(w, err)
109			return
110		}
111		s.publish(r.Context(), p.OrgID, "customer.updated", c)
112		writeJSON(w, http.StatusOK, c)
113	}
